/bin/bash -lc "cat <<'EOF' > src/util/ordersApi.mjs
/**
 * Normalizes the backend's order-list response (GET auth/orders, the one
 * RecentOrder.js loads) into a stable shape.
 *
 * Backend fields (ReadableOrderList / ReadableList):
 *   orders       - list of orders on this page
 *   pageCount    - number of pages
 *   totalRecords - total number of records
 *   itemsOnPage  - number of records on this page
 *
 * Missing values become an empty list or 0.
 */

const toNumber = (value) => {
  const num = typeof value === 'string' ? Number(value) : value;
  return typeof num === 'number' && Number.isFinite(num) ? num : 0;
};

export function normalizeOrderList(response) {
  const data = response && typeof response === 'object' ? response : {};

  const orders = Array.isArray(data.orders) ? data.orders : [];

  return {
    orders,
    pages: toNumber(data.pageCount),
    total: toNumber(data.totalRecords),
    onThisPage: toNumber(data.itemsOnPage),
  };
}

export default { normalizeOrderList };
EOF
node --input-type=module -e \"
import { normalizeOrderList } from './src/util/ordersApi.mjs';
console.log(JSON.stringify(normalizeOrderList({orders:[{id:1},{id:2}], pageCount:3, totalRecords:17, itemsOnPage:10})));
console.log(JSON.stringify(normalizeOrderList(null)));
console.log(JSON.stringify(normalizeOrderList({})));
console.log(JSON.stringify(normalizeOrderList({orders:'nope', pageCount:'2', totalRecords:5, itemsOnPage:null})));
\""
